export const createSelectAllOption = (
  element: HTMLGroupuiMultiselectOptionElement,
  selectAll: () => void,
  deselectAll: () => void
) => {
  const clickListener = () => {
    if (element.indeterminate) selectAll();
  };
  const checkedChangedListener = () => {
    if (element.checked) selectAll();
    else deselectAll();
  };
  const setState = (state: 'checked' | 'indeterminate' | 'unchecked') => {
    if (state === 'checked') {
      element.indeterminate = false;
      element.checked = true;
    } else if (state === 'indeterminate') {
      element.indeterminate = true;
    } else {
      element.checked = false;
      element.indeterminate = false;
    }
  };
  const addListener = () => {
    element.addEventListener('click', clickListener);
    element.addEventListener('checkedChanged', checkedChangedListener);
  };
  const removeListener = () => {
    element.removeEventListener('click', clickListener);
    element.removeEventListener('checkedChanged', checkedChangedListener);
  };
  return {
    element,
    setState,
    addListener,
    removeListener,
  };
};
export type SelectAllOption = ReturnType<typeof createSelectAllOption>;
