/* eslint-disable no-undef */
import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  Fragment,
  h,
  Host,
  Listen,
  Method,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import { HTMLStencilElement } from '@stencil/core/internal';
import { debounceTime, fromEvent, Observable, Subject, takeUntil } from 'rxjs';
import { CLEAR_SEARCH_BUTTON_LABEL } from '../../a11y';
import { FormDataEvent, FormSize, SelectedOption, SelectedOptionsEvent, Severity } from '../../types';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';
import { createSelectAllOption, SelectAllOption } from './select-all-option';

type SelectedMultiselectOption = { options: HTMLGroupuiMultiselectOptionElement[]; label: string };

type KeyboardFocus =
  | { type: 'none' }
  | { type: 'input' }
  | { type: 'clear' }
  | { type: 'search' }
  | { index: number; type: 'chip'; element: HTMLElement }
  | { index: number; type: 'option'; element: HTMLGroupuiMultiselectOptionElement }
  | { index: number; type: 'group'; element: HTMLGroupuiMultiselectOptionGroupElement };

type MultiselectItem =
  | { type: 'option'; element: HTMLGroupuiMultiselectOptionElement }
  | { type: 'expandable-option-group'; element: HTMLGroupuiMultiselectOptionGroupElement };

/**
 * @slot default - default slot for the content of the multiselect component (usually groupui-multiselect-option's)
 * @slot description - named slot 'description', here is any HTML content allowed.
 * @slot label - named slot 'label', here is any HTML content allowed.
 *
 * @nativeEvent click - dispatched when dropdown was clicked => 'event.target.value' delivers the value of current clicked option
 * @nativeEvent change - dispatched when the selection has changed. => 'event.detail' delivers the selectedOptions
 * @nativeEvent input - works only when searchable, dispatched on input => 'event.target.searchValue' delivers the value of input
 */
@Component({
  tag: 'groupui-multiselect',
  styleUrl: 'multiselect.scss',
  shadow: { delegatesFocus: true },
})
export class Multiselect implements ComponentInterface {
  private readonly optionsCountToken = '{count}';
  private readonly selectedOptionsToken = '{options}';
  private readonly allOptionsCountToken = '{countAll}';

  /**
   * severity of the multiselect component
   */
  @Prop({ reflect: true, mutable: true }) severity: Severity = 'none';

  /**
   * sets the size of the input field
   */
  @Prop({ reflect: true }) readonly size: FormSize = 'm';

  /**
   * name of the input element to support forms
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * placeholder of the multiselect component
   */
  @Prop({ reflect: true }) readonly placeholder: string;

  /**
   * set max-height for the options container (e.g. "200px")
   */
  @Prop({ reflect: true }) readonly maxHeight: string = 'none';

  /**
   * set max-height for the input container (e.g. "200px")
   */
  @Prop({ reflect: true }) readonly inputMaxHeight: string = 'none';

  /**
   * deactivates the multiselect component
   */
  @Prop({ reflect: true }) readonly disabled?: boolean;

  /**
   * toggles readonly mode
   */
  @Prop({ reflect: true }) readonly readonly: boolean;

  /**
   * show clear icon if at least one option is selected
   */
  @Prop({ reflect: true }) readonly showClearIcon: boolean;

  /**
   * sets focus automatically
   */
  @Prop({ reflect: true }) readonly autofocus: boolean;

  /**
   * show a customized summary instead of the default list of selected options. Use {count}, {countAll} and {options}
   * as template variables.
   */
  @Prop({ reflect: true }) readonly summary: string;

  /**
   * specifies that at least one option must be selected before submitting the form
   */
  @Prop({ reflect: true }) readonly required: boolean = false;

  /**
   * show status icon on severity danger, warning, success
   */
  @Prop({ reflect: true }) readonly showStatusIcon: boolean = false;

  /**
   * shows the description only when the component has focus
   */
  @Prop({ reflect: true }) readonly descriptionOnlyOnFocus: boolean = false;

  /**
   * disable internal validation
   */
  @Prop({ reflect: true }) readonly noValidation: boolean = false;

  /**
   * shows chips for selected options<br>
   * should not be used with size="s"
   */
  @Prop({ reflect: true }) readonly showChips: boolean = false;

  /**
   * position the chips below the multiselect
   */
  @Prop({ reflect: true }) readonly positionChipsBelow: boolean = false;

  /**
   * filters options only when show chips is activated
   */
  @Prop({ reflect: true }) readonly searchable: boolean = false;

  /**
   * value of the search-field
   */
  @Prop({ reflect: true, mutable: true }) searchValue: string;

  /**
   * returns the element's current validityState state (readonly value)
   */
  @Prop({ reflect: false, mutable: true }) validity: ValidityState;

  /**
   * shows selected options only on one line, does not work with chips
   */
  @Prop({ reflect: true }) readonly singleLine: boolean = false;

  /**
   * sets a custom accessible text for the clear button
   */
  @Prop({ reflect: true, attribute: 'a11y-label-clear-button' }) readonly a11yLabelClearButton: string;

  /**
   * toggle built-in search behaviour
   */
  @Prop({ reflect: true }) readonly builtInSearch: boolean = false;

  /**
   * makes the built-in search case-insensitive
   */
  @Prop({ reflect: true }) readonly caseInsensitiveSearch: boolean = false;

  /**
   * for react users only - use this instead of the native change event
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<SelectedOptionsEvent>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * works only when searchable. Is dispatched if the clear icon is clicked
   */
  @Event({ bubbles: false }) groupuiClearClicked: EventEmitter<void>;

  /**
   * works only when searchable. Is dispatched on keyboard enter or when search-icon is clicked => 'event.detail' delivers the selectedOptions
   */
  @Event({ bubbles: false }) groupuiSearchStarted: EventEmitter<SelectedOptionsEvent>;

  /**
   * works only when searchable. Is dispatched on keyboard escape or when clear-icon is clicked
   */
  @Event({ bubbles: false }) groupuiSearchCleared: EventEmitter<void>;

  /**
   * for react user only - works only when searchable. Is dispatched when the value is changed on key input
   */
  @Event({ bubbles: false }) groupuiInput: EventEmitter<void>;

  /**
   * works only when searchable. Is dispatched when the input is focused
   */
  @Event({ bubbles: false }) groupuiInputFocused: EventEmitter<void>;

  @State() expanded: boolean;
  @State() invalid: boolean;
  @State() hasFocus: boolean;
  @State() isEveryOptionFilteredOut: boolean;
  @State() searchOngoing: boolean;
  @State() keyboardFocus: KeyboardFocus = { type: 'none' };
  @State() private selectedMultiselectOptions: SelectedMultiselectOption[] = [];

  private readonly KEYBOARD_FOCUS = 'keyboard-focus';
  private tabbed: boolean;
  private ariaAttributes: AriaAttributes;

  private inputTyping = new Subject<string>();
  private outsideClick = new Observable<Event>();
  private destroy = new Subject<void>();

  private allItems: MultiselectItem[] = [];
  private selectableOptions: HTMLGroupuiMultiselectOptionElement[] = [];
  private focusableItems: (HTMLGroupuiMultiselectOptionElement | HTMLGroupuiMultiselectOptionGroupElement)[] = [];
  private selectAllOption?: SelectAllOption;
  private ignoreCheckedChangedEvents = false;

  @Element() host: HTMLElement;

  private subscribeToInputChanges() {
    const debouncedInputTyping = this.inputTyping.pipe(debounceTime(100));
    debouncedInputTyping.pipe(takeUntil(this.destroy)).subscribe((searchTerm) => {
      if (this.searchable && this.builtInSearch) {
        this.filterOptions(searchTerm);
        this.isEveryOptionFilteredOut = !this.isAnyOptionVisible();
      }
    });
  }

  @Watch('searchValue')
  onSearchValueChange(newSearchValue: string) {
    this.inputTyping.next(newSearchValue);
  }

  private filterOptions(searchTerm: string): void {
    this.getOptions().forEach((option) => {
      if (this.caseInsensitiveSearch) {
        option.invisible = !option.textContent.toLowerCase().includes(searchTerm.toLowerCase());
      } else {
        option.invisible = !option.textContent.includes(searchTerm);
      }
    });
    this.getGroups().forEach((group) => {
      const groupOptions = group.querySelectorAll('groupui-multiselect-option');
      group.invisible = Array.from(groupOptions).every((option) => option.invisible);
    });
    this.getGroups().forEach((group) => {
      const isChildOptionsMatchingSearchTerm = Array.from(group.querySelectorAll('groupui-multiselect-option')).some(
        (option) => !option.invisible
      );
      if (isChildOptionsMatchingSearchTerm) {
        group.collapsed = false;
      }
    });
    this.updateFocusableItems();
  }

  private getOptions() {
    return this.host.querySelectorAll('groupui-multiselect-option');
  }

  private getGroups() {
    return this.host.querySelectorAll('groupui-multiselect-option-group');
  }

  private iconSize() {
    return this.size === 's' ? 16 : 24;
  }

  @Listen('click', { capture: true })
  captureClick(event) {
    if (this.disabled || this.readonly) {
      event.stopPropagation();
    }

    this.searchable && !this.positionChipsBelow && this.getInputElement().focus();
  }

  @Listen('keydown')
  async onKeyDown(event: KeyboardEvent) {
    if (this.readonly) {
      return;
    }

    // focus last chip on ArrowLeft if input is focused and search input is empty
    if (this.keyboardFocus.type === 'input') {
      if (!this.searchOngoing && event.code === 'ArrowLeft') {
        this.focusPreviousChip();
        return;
      }

      if (event.code === 'Enter') {
        this.emitSearchStartedEvent();
        return;
      }
    }

    // skip keyboard handling during user search input
    if (this.keyboardFocus.type === 'input' && !['Escape', 'Tab', 'ArrowUp', 'ArrowDown'].includes(event.code)) return;

    if (event.code !== 'Tab') {
      event.preventDefault();
    }

    switch (event.code) {
      case 'Tab':
        this.tabbed = true;
        break;
      case 'Enter':
      case 'Space':
        this.showOptions();
        this.toggleActiveOption();
        break;
      case 'Escape':
        this.hideOptions();
        this.setKeyboardFocus(this.searchable ? { type: 'input' } : { type: 'none' });
        this.searchOngoing = false;
        this.clearSearchField();
        break;
      case 'ArrowLeft':
        if (this.keyboardFocus?.type === 'group') {
          this.keyboardFocus.element.collapsed = true;
        } else this.focusPreviousChip();
        break;
      case 'ArrowRight':
        if (this.keyboardFocus?.type === 'group') {
          this.keyboardFocus.element.collapsed = false;
        } else this.focusNextChip();
        break;
      case 'ArrowDown':
        this.focusOption('next');
        break;
      case 'ArrowUp':
        this.focusOption('previous');
        break;
      case 'Backspace':
        this.clickActiveChip();
        break;
    }
  }

  private clearSearchField() {
    const inputElement = this.getInputElement();
    if (!inputElement) return;

    if (inputElement.value?.length > 0) {
      inputElement.value = '';
      this.searchValue = '';
      this.groupuiSearchCleared.emit();
    }
  }

  private emitSearchStartedEvent() {
    this.groupuiSearchStarted.emit({ selectedOptions: this.getEventSelectedOptions(), searchString: this.searchValue });
  }

  @Listen('groupuiCollapsedChanged')
  onOptionGroupCollapseChanged() {
    this.updateFocusableItems();
  }

  @Listen('groupuiParentCheckedChanged')
  onParentCheckboxChanged(event: CustomEvent<boolean>) {
    const options = (event.target as HTMLGroupuiMultiselectOptionGroupElement).querySelectorAll(
      'groupui-multiselect-option'
    );
    this.changeMultipleOptions(Array.from(options), event.detail);
  }

  @Listen('checkedChanged')
  async onCheckedChanged(event: CustomEvent<HTMLGroupuiMultiselectOptionElement>) {
    if (event.target === this.selectAllOption?.element || this.ignoreCheckedChangedEvents) return;
    this.updateItems();
  }

  private updateItems() {
    this.handleOptionChange();
    this.focusSelectedOptions();
    this.validateMultiselect();
  }

  @Listen('focus')
  onFocus() {
    this.hasFocus = true;
    if (this.searchable) this.getInputElement()?.focus();
  }

  @Listen('blur')
  onBlur(event: FocusEvent) {
    this.hasFocus = false;
    this.setKeyboardFocus({ type: 'none' });

    if (this.tabbed) {
      this.tabbed = false;

      if (!this.newFocusInChild(event)) {
        this.hideOptions();
        if (this.searchable) {
          this.clearSearchField();
        }
        this.searchOngoing = false;
      }
    }
  }

  private newFocusInChild(event: FocusEvent) {
    const currentTarget = event.currentTarget as Node;
    const relatedTarget = event.relatedTarget as Node | null;
    return event.relatedTarget && currentTarget.contains(relatedTarget);
  }

  @Watch('expanded')
  onExpandedChanged() {
    if (!this.expanded) {
      this.validateMultiselect();
      this.searchOngoing = false;
    }
  }

  @Watch('invalid')
  onInvalidChange() {
    this.validity = this.getValidity();
    this.invalid ? (this.severity = 'danger') : (this.severity = null);
  }

  /**
   * function to trigger component validation manually
   */
  @Method()
  async validate() {
    this.validateMultiselect({ force: true });
  }

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.subscribeToInputChanges();
    this.subscribeToOutsideClicks();
  }

  private subscribeToOutsideClicks() {
    this.outsideClick = fromEvent(document, 'click').pipe(takeUntil(this.destroy));
    this.outsideClick.subscribe((event: Event) => {
      this.handleOutsideClick(event);
    });
  }

  private isAnyOptionVisible(): boolean {
    return Array.from(this.getOptions()).some((option) => {
      return !option.invisible;
    });
  }

  private isAnyOptionAvailable(): boolean {
    return this.getOptions().length > 0;
  }

  async componentDidLoad() {
    await this.waitForParentsOnReady();
    this.thereCanBeOnlyOneSelectAll();
    this.autofocus && this.host.focus && this.host.focus();
    this.addFormsHandling();
    this.addAutoGrowingInput();
    this.validity = this.getValidity();

    this.groupuiDidLoad.emit();
  }

  private thereCanBeOnlyOneSelectAll() {
    if (this.host.querySelectorAll('groupui-multiselect-option[select-all=""]').length > 1) {
      console.warn('Only one multiselect-option with select-all per multiselect allowed');
    }
  }

  private addAutoGrowingInput() {
    if (this.searchable) {
      this.getInputElement().addEventListener('input', () => this.triggerAutoGrowing());
    }
  }

  private triggerAutoGrowing() {
    const input = this.getInputElement();
    const inputWidth: HTMLSpanElement = this.host.shadowRoot.querySelector('#input-width');
    const selectedOptions: HTMLDivElement = this.host.shadowRoot.querySelector('#selected-options-wrapper');

    // In Safari the caret takes up space inside the input
    const caretWidth = 2;
    inputWidth.innerHTML = input.value.replace(/\s/g, '&nbsp;');
    if (selectedOptions.offsetWidth > inputWidth.offsetWidth) {
      input.style.width = inputWidth.offsetWidth + caretWidth + 'px';
    }
  }

  private setKeyboardFocus(keyboardFocus: KeyboardFocus) {
    this.removeKeyboardFocus();
    this.keyboardFocus = keyboardFocus;
    this.applyKeyboardFocus();
  }

  private validateMultiselect({ force = false }: { force?: boolean } = {}) {
    if (!force && this.noValidation) return;
    this.invalid = !this.getValidity().valid;
  }

  private getValidity() {
    return {
      valid: this.anyOptionSelected() || !this.required,
      valueMissing: this.required && !this.anyOptionSelected(),
      badInput: false,
      customError: false,
      patternMismatch: false,
      rangeOverflow: false,
      rangeUnderflow: false,
      stepMismatch: false,
      tooLong: false,
      tooShort: false,
      typeMismatch: false,
    };
  }

  private async waitForParentsOnReady() {
    const multiselect = document.querySelector('groupui-multiselect');

    if (multiselect) {
      let parent = multiselect.parentElement as HTMLStencilElement;
      while (parent.componentOnReady) {
        await parent.componentOnReady();
        parent = parent.parentElement as HTMLStencilElement;
      }
    }
  }

  disconnectedCallback() {
    this.destroy.next();
    this.destroy.complete();
  }

  private handleOutsideClick = (event: Event) => {
    if (this.expanded && !event.composedPath().includes(this.host)) {
      this.hideOptions();
      if (this.searchable) {
        this.clearSearchField();
        this.triggerAutoGrowing();
        this.searchOngoing = false;
        this.setKeyboardFocus({ type: 'none' });
      }
    }
  };

  private handleClearIconClick = (e: MouseEvent) => {
    e.stopPropagation();
    if (!this.searchOngoing) {
      this.selectAllOption?.removeListener();
      this.changeAllOptions(false);
      this.selectAllOption?.addListener();
      this.groupuiClearClicked.emit();
    } else {
      this.clearInput();
      this.searchValue = '';
      this.groupuiSearchCleared.emit();
    }
  };

  private showOptions() {
    this.expanded = true;
  }

  private hideOptions() {
    this.expanded = false;
  }

  private removeKeyboardFocus() {
    if (
      this.keyboardFocus.type === 'option' ||
      this.keyboardFocus.type === 'group' ||
      this.keyboardFocus.type === 'chip'
    ) {
      this.keyboardFocus.element.classList.remove(this.KEYBOARD_FOCUS);
    }
  }

  private applyKeyboardFocus() {
    if (this.keyboardFocus.type === 'none') return;

    switch (this.keyboardFocus.type) {
      case 'input':
        this.searchable && this.getInputElement().focus();
        break;
      case 'chip':
      case 'group':
      case 'option':
        this.keyboardFocus.element.scrollIntoView({ block: 'nearest' });
        this.keyboardFocus.element.classList.add(this.KEYBOARD_FOCUS);
        if (this.keyboardFocus.type !== 'chip') this.showOptions();
        break;
    }
  }

  private getVisibleOptionEntries(): {
    index: number;
    option: HTMLGroupuiMultiselectOptionElement | HTMLGroupuiMultiselectOptionGroupElement;
  }[] {
    return this.focusableItems.map((option, index) => ({ index, option }));
  }

  private focusOption(direction: 'next' | 'previous') {
    const optionEntries = this.getVisibleOptionEntries();
    if (optionEntries.length === 0) return;
    const keyboardFocus = this.keyboardFocus;
    if (!keyboardFocus || (keyboardFocus.type !== 'option' && keyboardFocus.type !== 'group')) {
      const initialIndex = direction === 'next' ? 0 : optionEntries.length - 1;
      this.setFocusToItem(optionEntries[initialIndex]);
      return;
    }
    const currentOptionIndex = keyboardFocus?.index;
    if (
      this.searchable &&
      ((direction === 'next' && currentOptionIndex + 1 >= optionEntries.length) ||
        (direction === 'previous' && currentOptionIndex - 1 < 0))
    ) {
      this.setKeyboardFocus({ type: 'input' });
      return;
    }
    const newEntryIndex =
      direction === 'next'
        ? (currentOptionIndex + 1) % optionEntries.length
        : (currentOptionIndex - 1 + optionEntries.length) % optionEntries.length;

    this.setFocusToItem(optionEntries[newEntryIndex]);
  }

  private setFocusToItem(item: { index: number; option: Element }) {
    if (item.option.tagName === 'GROUPUI-MULTISELECT-OPTION') {
      this.setKeyboardFocus({
        type: 'option',
        index: item.index,
        element: item.option as HTMLGroupuiMultiselectOptionElement,
      });
    } else {
      this.setKeyboardFocus({
        type: 'group',
        index: item.index,
        element: item.option as HTMLGroupuiMultiselectOptionGroupElement,
      });
    }
  }

  private toggleActiveOption(): void {
    if (this.keyboardFocus?.type === 'group') {
      this.keyboardFocus.element.click();
    } else if (this.keyboardFocus.type === 'option') {
      this.keyboardFocus.element.checked = !this.keyboardFocus.element.checked;
    }
  }

  private getChips(): HTMLGroupuiChipElement[] {
    return Array.from(this.host.shadowRoot.querySelectorAll('groupui-chip'));
  }

  private focusNextChip() {
    const chips = this.getChips();
    if (chips.length === 0) return;
    if (this.keyboardFocus.type !== 'chip') {
      this.setKeyboardFocus({ type: 'chip', index: 0, element: chips[0] });
    } else if (this.searchable && this.keyboardFocus.index + 1 >= chips.length) {
      this.setKeyboardFocus({ type: 'input' });
    } else {
      const index = Math.min(chips.length - 1, this.keyboardFocus.index + 1);
      this.setKeyboardFocus({
        type: 'chip',
        index,
        element: chips[index],
      });
    }
  }

  private focusPreviousChip() {
    const chips = this.getChips();
    if (chips.length === 0) return;
    if (this.keyboardFocus.type !== 'chip') {
      const index = chips.length - 1;
      this.setKeyboardFocus({ type: 'chip', index, element: chips[index] });
    } else {
      const index = Math.max(0, this.keyboardFocus.index - 1);
      this.setKeyboardFocus({ type: 'chip', index, element: chips[index] });
    }
  }

  private focusNextChipAfterDelete() {
    if (this.keyboardFocus.type !== 'chip') return;
    const chips = this.getChips();
    if (chips.length > 0) {
      const index = Math.max(0, this.keyboardFocus.index - 1);
      this.setKeyboardFocus({
        type: 'chip',
        index,
        element: chips[index],
      });
    } else if (this.searchable) {
      this.setKeyboardFocus({ type: 'input' });
    } else {
      this.setKeyboardFocus({ type: 'none' });
    }
  }

  private clickActiveChip() {
    if (this.keyboardFocus.type === 'chip') {
      this.getChips()[this.keyboardFocus.index]?.click();
    }
  }

  private addFormsHandling() {
    if (this.name === undefined) return;

    const form = this.host.closest('form');
    if (form == null) return;

    form.addEventListener('formdata', (event: FormDataEvent) => {
      this.getSelectedOptions().forEach((option) => {
        event.formData.append(this.name, option.value);
      });
    });

    form.addEventListener('submit', (event: Event) => {
      this.validateMultiselect();
      if (this.invalid) {
        event.preventDefault();
      }
    });
  }

  private handleOptionChange() {
    this.updateSelectedMultiselectOptions();
    this.dispatchEvents();
  }

  private updateSelectedMultiselectOptions() {
    const selectedOptions = this.selectableOptions.filter((option) => option.checked);
    const selectedMultiselectOptions: SelectedMultiselectOption[] = [];
    this.allItems.forEach((item) => {
      if (item.type === 'option' && selectedOptions.includes(item.element)) {
        selectedMultiselectOptions.push({ options: [item.element], label: this.filterOptionLabel(item.element) });
      } else if (item.type === 'expandable-option-group') {
        const optionGroupOptions = Array.from(item.element.querySelectorAll('groupui-multiselect-option'));
        if (optionGroupOptions.every((option) => option.checked)) {
          selectedMultiselectOptions.push({
            label: item.element.label,
            options: optionGroupOptions as HTMLGroupuiMultiselectOptionElement[],
          });
        } else {
          selectedMultiselectOptions.push(
            ...optionGroupOptions
              .filter((option) => option.checked)
              .map((option) => {
                return { options: [option], label: this.filterOptionLabel(option) };
              })
          );
        }
      }
    });
    this.selectedMultiselectOptions = selectedMultiselectOptions;
    this.updateSelectAllState();
  }

  private filterOptionLabel(option: HTMLGroupuiMultiselectOptionElement): string {
    let htmlContent = option.innerHTML?.trim();
    let start: number, end: number;
    if (option.querySelector('[slot="description"]')) {
      start = htmlContent.indexOf(option.querySelector('[slot="description"]').outerHTML);
      end = option.querySelector('[slot="description"]').outerHTML.length;
      if (start === 0) {
        htmlContent = htmlContent.substring(end);
      } else {
        htmlContent = htmlContent.substring(0, start);
      }
    }
    return htmlContent.trim();
  }

  private dispatchEvents() {
    const eventSelectedOptions = this.getEventSelectedOptions();
    this.host.dispatchEvent(
      new CustomEvent('change', { detail: { selectedOptions: eventSelectedOptions, searchString: this.searchValue } })
    );
    this.groupuiChange.emit({ selectedOptions: eventSelectedOptions, searchString: this.searchValue });
  }

  private getSelectedOptions(): HTMLGroupuiMultiselectOptionElement[] {
    return this.selectedMultiselectOptions.flatMap((option) => option.options);
  }

  private updateSelectAllState() {
    const selectedOptionsCount = this.getSelectedOptions().length;
    this.selectAllOption?.setState(
      selectedOptionsCount === 0
        ? 'unchecked'
        : selectedOptionsCount === this.selectableOptions.length
          ? 'checked'
          : 'indeterminate'
    );
  }

  private changeMultipleOptions(options: HTMLGroupuiMultiselectOptionElement[], checked: boolean) {
    this.ignoreCheckedChangedEvents = true;
    options.forEach((option) => {
      option.checked = checked;
    });
    this.ignoreCheckedChangedEvents = false;
    this.updateItems();
  }

  private changeAllOptions(checkedState: boolean) {
    this.changeMultipleOptions(this.selectableOptions, checkedState);
  }

  private getEventSelectedOptions(): SelectedOption[] {
    return this.getSelectedOptions().map((option) => {
      return { value: option.value, content: option.innerText };
    });
  }

  private removeOptionFromSelection(option: SelectedMultiselectOption) {
    this.changeMultipleOptions(option.options, false);
    this.focusNextChipAfterDelete();
  }

  private renderSelectedOptions(): string {
    if (this.summary && !this.isPlaceholderVisible()) {
      return this.summary
        .replace(this.optionsCountToken, `${this.getSelectedOptions().length}`)
        .replace(this.allOptionsCountToken, `${this.selectableOptions.length}`)
        .replace(this.selectedOptionsToken, this.joinSelectedOptions());
    } else {
      return this.joinSelectedOptions();
    }
  }

  private isPlaceholderVisible() {
    if (!this.placeholder || this.placeholder === '') return false;
    if (this.searchable && this.hasFocus) return false;
    return this.getSelectedOptions().length === 0 || this.positionChipsBelow;
  }

  private anyOptionSelected(): boolean {
    return Array.from(this.selectableOptions).some((option) => option.checked);
  }

  private focusSelectedOptions() {
    const selectedOptions = this.host.shadowRoot.querySelector('#selected-options') as HTMLElement;
    selectedOptions && selectedOptions.focus && selectedOptions.focus();
  }

  private joinSelectedOptions() {
    return this.selectedMultiselectOptions.map((selectedOption) => selectedOption.label).join(', ');
  }

  private createChips() {
    return this.selectedMultiselectOptions.map((option) => (
      <groupui-chip
        embedded={true}
        disabled={this.disabled}
        color="light"
        onClick={() => this.removeOptionFromSelection(option)}
      >
        <span innerHTML={option.label} />
        {!this.disabled && (
          <div slot="end">
            <groupui-icon name="close-16"></groupui-icon>
          </div>
        )}
      </groupui-chip>
    ));
  }

  private toggleExpanded = (event: Event) => {
    const element = event.target as HTMLElement;
    const targetChip = element.closest('groupui-chip');

    if (!(targetChip && targetChip.nodeName === 'GROUPUI-CHIP') && !this.searchOngoing) {
      this.expanded = !this.expanded;
      this.focusSelectedOptions();
    }
  };

  private isLabelSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="label"]');
  }

  private isDescriptionSlotProvided(): boolean {
    return Array.from(this.host.children).some((option) => {
      return option.getAttribute('slot') === 'description';
    });
  }

  private useStatusIcon() {
    return this.showStatusIcon && this.severity && this.severity !== 'none';
  }

  private getStatusIcon() {
    switch (this.severity) {
      case 'warning':
        return `warning-filled-${this.iconSize()}`;
      case 'danger':
        return `error-filled-${this.iconSize()}`;
      case 'success':
        return `success-filled-${this.iconSize()}`;
    }
  }

  private showDescription() {
    return !this.descriptionOnlyOnFocus ? true : this.hasFocus;
  }

  private updateFocusableItems() {
    const focusableItems: (HTMLGroupuiMultiselectOptionElement | HTMLGroupuiMultiselectOptionGroupElement)[] = [];
    this.allItems.forEach((item) => {
      if (item.element.invisible) return;
      if (item.type === 'option') {
        focusableItems.push(item.element);
      } else if (item.type === 'expandable-option-group') {
        focusableItems.push(item.element);
        if (!item.element.collapsed) {
          const options = Array.from(item.element.querySelectorAll('groupui-multiselect-option'));
          options.forEach((child) => {
            if (!child.invisible) {
              focusableItems.push(child);
            }
          });
        }
      }
    });
    this.focusableItems = focusableItems;
  }

  private assembleItemsList(assignedElements: Element[]) {
    const allItems: MultiselectItem[] = [];
    const selectableOptions: HTMLGroupuiMultiselectOptionElement[] = [];

    assignedElements.forEach((element) => {
      const processElement = (element) => {
        if (element.tagName === 'GROUPUI-MULTISELECT-OPTION') {
          allItems.push({ type: 'option', element });
          selectableOptions.push(element);
        } else if (element.tagName === 'GROUPUI-MULTISELECT-OPTION-GROUP' && element.hasAttribute('expandable')) {
          allItems.push({ type: 'expandable-option-group', element });
          element.childNodes.forEach((child) => {
            if (child.tagName === 'GROUPUI-MULTISELECT-OPTION') {
              selectableOptions.push(child);
            }
          });
        } else if (element.tagName === 'GROUPUI-MULTISELECT-OPTION-GROUP') {
          element.childNodes.forEach((child) => {
            processElement(child);
          });
        }
      };
      processElement(element);
    });
    this.allItems = allItems;
    this.setupSelectAllOption(selectableOptions);
    this.selectableOptions = selectableOptions.filter((option) => !option.selectAll);
    this.updateFocusableItems();
    this.handleOptionChange();
    this.updateSelectAllState();
  }

  private setupSelectAllOption(selectableOptions: HTMLGroupuiMultiselectOptionElement[]) {
    this.selectAllOption?.removeListener();
    const selectAll = selectableOptions.find((option) => option.selectAll);
    if (selectAll) {
      this.selectAllOption = createSelectAllOption(
        selectAll,
        () => {
          this.changeAllOptions(true);
        },
        () => {
          this.changeAllOptions(false);
        }
      );
      this.selectAllOption.addListener();
    }
  }

  private handleOptionSlotChanged = async (event: Event) => {
    const slot = event.target as HTMLSlotElement;
    this.assembleItemsList(slot.assignedElements());
  };

  private getInputElement(): HTMLInputElement {
    return this.host.shadowRoot.querySelector('input');
  }

  private handleInput = () => {
    const inputValue = this.getInputElement().value;
    this.searchOngoing = inputValue !== '';
    this.searchValue = inputValue;
    this.showOptions();
    this.groupuiInput.emit();
  };

  private clearInput = () => {
    const input = this.getInputElement();
    input.value = '';
    this.searchValue = '';
    this.searchable && this.triggerAutoGrowing();
    this.searchOngoing = false;
    input.focus();
  };

  private setInputFocus = () => {
    this.setKeyboardFocus({ type: 'input' });
    this.groupuiInputFocused.emit();
  };

  private isClearIconVisible() {
    return this.searchOngoing || (this.showClearIcon && this.anyOptionSelected());
  }

  private setSubFocus = (event) => {
    if (this.tabbed) {
      this.setKeyboardFocus({ type: event.target.id });
    }
  };

  private isPopoverVisible(): boolean {
    return this.expanded && !this.isEveryOptionFilteredOut && this.isAnyOptionAvailable();
  }

  render() {
    return (
      <Host>
        {this.isLabelSlotProvided() && (
          <label id="label" onClick={this.toggleExpanded} aria-hidden="true">
            <slot name="label" />
          </label>
        )}
        <div id="input-wrapper" tabIndex={this.disabled || this.searchable ? -1 : 0}>
          <groupui-popover
            visible={this.isPopoverVisible()}
            full-width={true}
            max-height={this.maxHeight}
            offset={undefined}
          >
            <div
              slot="parent"
              role="combobox"
              id="select"
              onClick={this.toggleExpanded}
              class={this.expanded ? 'expanded' : undefined}
              aria-labelledby={this.isLabelSlotProvided() ? 'label' : undefined}
              aria-describedby={this.isDescriptionSlotProvided() ? 'description' : undefined}
              aria-expanded={this.expanded ? 'true' : 'false'}
              aria-controls="content"
              {...this.ariaAttributes}
            >
              <div
                id="container"
                style={{ maxHeight: this.inputMaxHeight }}
                class={{
                  expanded: this.expanded,
                  filled: this.getSelectedOptions().length > 0,
                  statusicon: this.useStatusIcon(),
                  'sub-focus': this.keyboardFocus.type === 'clear' || this.keyboardFocus.type === 'search',
                }}
              >
                <div id="selected-options-wrapper">
                  <div id="selected-options">
                    {this.isPlaceholderVisible() && <div id="placeholder">{this.placeholder}</div>}
                    {this.showChips && !this.positionChipsBelow && this.createChips()}
                    {!this.showChips && <span innerHTML={this.renderSelectedOptions()} />}
                  </div>
                  {this.searchable && (
                    <Fragment>
                      <div id="input-width-wrapper">
                        <input
                          class={this.keyboardFocus.type === 'input' ? 'input-focus' : ''}
                          onInput={this.handleInput}
                          onFocus={this.setInputFocus}
                          tabindex={0}
                          disabled={this.disabled}
                          readonly={this.readonly}
                          value={this.searchValue}
                          aria-labelledby={this.isLabelSlotProvided() ? 'label' : undefined}
                          aria-describedby={this.isDescriptionSlotProvided() ? 'description' : undefined}
                          {...this.ariaAttributes}
                        ></input>
                        <span id="input-width" aria-hidden="true"></span>
                      </div>
                    </Fragment>
                  )}
                </div>
                <div id="icons">
                  {this.useStatusIcon() && (
                    <groupui-icon
                      id="status-icon"
                      name={this.getStatusIcon()}
                      width={this.iconSize()}
                      height={this.iconSize()}
                      aria-hidden="true"
                    />
                  )}
                  {this.isClearIconVisible() && (
                    <groupui-embedded-button
                      id="clear"
                      onClick={this.handleClearIconClick}
                      onFocus={this.setSubFocus}
                      class={this.keyboardFocus.type === 'clear' ? 'focused' : ''}
                      aria-label={this.a11yLabelClearButton ? this.a11yLabelClearButton : CLEAR_SEARCH_BUTTON_LABEL}
                      aria-describedby={this.isLabelSlotProvided() && !this.a11yLabelClearButton ? 'label' : null}
                      aria-hidden={this.disabled || this.readonly ? 'true' : null}
                      disabled={this.disabled || this.readonly}
                      icon={`close-${this.iconSize()}`}
                      size={this.size === 'm' ? 'xs' : 'xxs'}
                    />
                  )}
                  <groupui-icon id="chevron" name={`chevron-down-${this.iconSize()}`} aria-hidden="true" />
                </div>
              </div>
            </div>
            <div slot="content" id="content" style={{ maxHeight: this.maxHeight }}>
              <slot onSlotchange={this.handleOptionSlotChanged} />
            </div>
          </groupui-popover>
        </div>
        {this.isDescriptionSlotProvided() && this.showDescription() && (
          <div id="description" onClick={this.toggleExpanded} aria-hidden="true">
            <slot name="description" />
          </div>
        )}
        {this.showChips && this.positionChipsBelow && (
          <div
            id="outer-chips-container"
            onMouseDown={(e) => {
              e.preventDefault();
            }}
          >
            {this.createChips()}
          </div>
        )}
      </Host>
    );
  }
}
